function latest(type=page){const {context,routeId,selected,weights,tasks}=agentView(type);return tasks.find(t=>t.agentType===type&&t.projectId===context.project.id&&t.projectVersion===context.project.version&&(type==='comparison'?JSON.stringify([...t.routeIds].sort())===JSON.stringify([...selected].sort())&&JSON.stringify(t.result?.weights)===JSON.stringify(weights):t.routeIds.includes(routeId)))}
function statusTag(t){return t?.status==='simulation_completed'?'<span class="tag">模拟流程已完成</span>':t?.status==='confirmed'?'<span class="tag">人工已确认</span>':t?.status==='running'?'<span class="tag blue">生成中</span>':t?.status==='failed'?'<span class="tag amber">生成失败</span>':t?'<span class="tag amber">待人工确认</span>':'<span class="tag gray">尚未生成</span>'}
function metric(title,value,unit,foot,ic){return `<div class="metric"><span class="accent"></span><div class="metric-title">${title}${icon(ic)}</div><div class="metric-val">${value}<small>${unit}</small></div><div class="metric-foot">${foot}</div></div>`}
function projectIsRunning(){return tasks.some(t=>t.projectId===context.project.id&&t.projectVersion===context.project.version&&t.status==='running')}
