 if(usesAgentSample()){const p=agentSample.context.project;return `<section class="panel agent-sample-context"><div><span class="project-manager-label">样例工程</span><strong>${esc(p.name)}</strong><span class="tag">${esc(p.voltage)}</span></div><span class="tag gray">样例页面</span></section>`;}
 const p=context.project,disabled=!p.id||projectIsRunning()?'disabled':'';
 return `<section class="panel project-manager" aria-label="工程管理"><div class="project-manager-info"><span class="project-manager-label">当前工程</span><div class="project-manager-name">${p.id?`<button class="project-name-button" data-action="project" title="查看工程信息">${icon('folder')}<strong>${esc(p.name)}</strong></button>`:'<strong class="muted">尚未选择工程</strong>'}</div></div><div class="project-manager-tools"><details class="project-menu"><summary>工程管理${icon('down')}</summary><div class="project-menu-items"><button data-action="new-project">新建工程</button><button data-action="switch-project" ${projects.length||deletedProjects.length?'':'disabled'}>切换工程</button><button data-action="edit-project-input" ${disabled}>编辑工程</button><button class="project-delete-button" data-action="delete-project" ${disabled}>删除工程</button></div></details>${p.id?'<small id="database-save-state" class="muted"></small>':''}${generationActions?`<div class="actions letter-generation-actions">${generationActions}</div>`:''}</div></section>`;
