document.addEventListener('click',e=>{if(e.button!==0)return;if(!e.target.closest('.letter-more'))document.querySelectorAll('.letter-more[open]').forEach(menu=>menu.open=false);if(!e.target.closest('.project-menu'))document.querySelectorAll('.project-menu[open]').forEach(menu=>menu.open=false);if(!e.target.closest('.settings-menu'))closeSettingsMenu();const b=e.target.closest('[data-action]');if(b?.closest('.settings-dropdown'))closeSettingsMenu();if(!b)return;const projectMenu=b.closest('.project-menu');if(projectMenu)projectMenu.open=false;if(b.dataset.action==='letter-ui'){handleLetters(b);return}const f=actions[b.dataset.action];if(f)f(b)});
document.addEventListener('compositionstart',e=>{if(e.target.id==='letter-agreement-search')e.target.dataset.composing='true'});
document.addEventListener('compositionend',e=>{if(e.target.id==='letter-agreement-search'){delete e.target.dataset.composing;searchLetterAgreements(e.target.value)}});
