document.addEventListener('input',e=>{if(e.target.id==='letter-agreement-search'&&!e.isComposing)searchLetterAgreements(e.target.value);if(e.target.id==='chapter-editor'){const t=latest('description');if(t)drafts.set(t.id,e.target.value)}});
document.addEventListener('change',e=>{if(e.target.matches('.route-checkbox')){const id=e.target.dataset.route;if(usesAgentSample())agentSample.selected=e.target.checked?[...new Set([...agentSample.selected,id])]:agentSample.selected.filter(x=>x!==id);else selected=e.target.checked?[...new Set([...selected,id])]:selected.filter(x=>x!==id);render()}if(e.target.id==='project-select'){switchProject(e.target.value);switchProjectModal();return}if(e.target.id==='route-select'){routeId=e.target.value;issueId=context.issues.find(i=>i.routeIds.includes(routeId))?.id;letterIndex=0;persist();render();switchProjectModal()}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('g[data-action]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(pageNames[p]&&p!==page){page=p;render()}});
let databaseSync;
function queueWorkspace(){if(config.mode!=='demo')databaseSync?.enqueue(projectRecords(rememberProject(projects,context,routeId,selected),deletedProjects,localStorage));}
async function saveWorkspace(){queueWorkspace();await databaseSync?.flush();}
async function loadDatabaseWorkspace(){
 if(config.mode==='demo')return;
 try{
  databaseSync=createDatabaseSync({request,storage:localStorage,onStatus:status=>{const label=document.querySelector('#database-save-state');if(label)label.textContent=({saving:'正在保存',saved:'已保存到数据库',error:'数据库保存失败',local:'本机文件模式'})[status]||''},onError:error=>toast(error.message)});
  const activeKey=projectKey(context),records=await databaseSync.load(projectRecords(projects,deletedProjects,localStorage));
  if(!records)return;
  projects=records.filter(r=>!r.hidden&&!r.deleted).map(r=>r.entry);deletedProjects=records.filter(r=>!r.hidden&&r.deleted).map(r=>r.entry);
  for(const record of records.filter(r=>!r.hidden))for(const [id,state] of Object.entries(record.workingCopies||{}))localStorage.setItem('tx-letters-v2-'+record.entry.context.project.id+'-'+record.entry.context.project.version+'-'+id,JSON.stringify({...state,importToken:crypto.randomUUID()}));
  const activeProject=projects.find(p=>p.key===activeKey);
  if(activeProject){context=clone(activeProject.context);routeId=activeProject.routeId;selected=activeProject.selected;projectImported=true;}
  else if(context.project.id){context=emptyWorkspace();routeId='';selected=[];projectImported=false;}
  const remote=await request('/api/v1/tasks');tasks=remote.tasks;persist();render();
 }catch(error){toast('数据库资料未加载：'+error.message+'。当前输入仍保留在浏览器中');}
}
attachDialogBackdropClose($('#dialog'));
render();
loadDatabaseWorkspace();

document.addEventListener('focusin',e=>{if(!e.target.closest('.settings-menu'))closeSettingsMenu()});
document.addEventListener('keydown',e=>{
 const menu=$('#settings-dropdown'),trigger=$('[data-action="settings"]');if(!menu||!trigger)return;
 const inMenu=menu.contains(e.target),onTrigger=e.target===trigger;
 if(e.key==='Escape'&&!menu.hidden){e.preventDefault();closeSettingsMenu();trigger.focus();return}
 if((e.key==='ArrowDown'||e.key==='ArrowUp')&&(inMenu||onTrigger)){
  e.preventDefault();if(menu.hidden)toggleSettingsMenu();const items=[...menu.querySelectorAll('[role="menuitem"]')],index=items.indexOf(e.target);const next=index<0?(e.key==='ArrowUp'?items.length-1:0):(index+(e.key==='ArrowUp'?-1:1)+items.length)%items.length;items[next]?.focus();
 }
 if(inMenu&&(e.key==='Home'||e.key==='End')){e.preventDefault();const items=[...menu.querySelectorAll('[role="menuitem"]')];items[e.key==='Home'?0:items.length-1]?.focus()}
});

document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;const more=document.querySelector('.letter-more[open]');if(more){more.open=false;more.querySelector('summary')?.focus();}});
